#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Wires production to Sentry (#67): the Potluck project in the existing Sentry
# org, Sentry's Vercel integration (it puts the DSN and the build token into
# Vercel, so nobody copies a key), and an uptime monitor on the liveness route.
# Run from the repo root, signed in to the Vercel CLI (no link needed):
#   scripts/setup-monitoring.sh
# It writes nothing to .env.local, .vercel/ or GitHub, and prints no variable's
# value: stage 5 lists Vercel's Sentry variables by name and target only.

VERCEL_CLI="vercel@65.5.0"
LIVENESS_URL="https://potluck-zeta.vercel.app/api/live"
SENTRY_KEYS=(NEXT_PUBLIC_SENTRY_DSN SENTRY_AUTH_TOKEN SENTRY_ORG SENTRY_PROJECT)

run_wizard() {

TOTAL_STAGES=6

if [[ ! -f package.json || ! -d node_modules ]]; then
  printf 'Run this from the repo root, after npm install.\n' >&2
  exit 1
fi
if ! command -v jq >/dev/null 2>&1; then
  printf 'Stage 5 needs jq. Install it, then re-run.\n' >&2
  exit 1
fi

banner "Potluck monitoring: Sentry errors and uptime"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sentry: create the project"
open_url "https://sentry.io/projects/new/"
step "Sign in to the existing org if asked."
step "Platform: Next.js."
step "Alerts: keep the option that emails you when a new issue appears"
step "  (not \"I'll create my own alerts later\")."
step "Project name: potluck. Team: the default one. Click Create Project."
note "Sentry then shows its setup steps (the @sentry/wizard command). Skip them:"
note "the SDK is already in the app (#66)."
step "Copy the org slug from the address bar: sentry.io/organizations/<slug>/…"
step "  or <slug>.sentry.io/…"
while :; do
  ask SENTRY_ORG_SLUG "Org slug:"
  [[ "$SENTRY_ORG_SLUG" =~ ^[a-z0-9][a-z0-9_-]*$ ]] && break
  warn "A slug is lowercase letters, digits, - and _. Try again."
done
pause "Press Enter once the potluck project exists."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sentry: read the org's data region"
say "The privacy page names where Sentry keeps the errors."
open_url "https://sentry.io/settings/$SENTRY_ORG_SLUG/"
step "On the org's General Settings, look for Data Storage Location."
note "If it isn't shown: an address on de.sentry.io means EU (Germany);"
note "us.sentry.io, or plain sentry.io, means US."
while :; do
  ask SENTRY_REGION "Region (US or EU):"
  SENTRY_REGION=$(printf '%s' "$SENTRY_REGION" | tr '[:lower:]' '[:upper:]')
  [[ "$SENTRY_REGION" == US || "$SENTRY_REGION" == EU ]] && break
  warn "Type US or EU."
done
printf '  %s✓ region%s %s\n' "$GREEN" "$RESET" "$SENTRY_REGION"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Sentry: never store IP addresses"
say "The app never sends IPs (#66). This makes Sentry drop any that slip through."
open_url "https://sentry.io/settings/$SENTRY_ORG_SLUG/projects/potluck/security-and-privacy/"
note "If that page doesn't open: Settings → Projects → potluck → Security & Privacy."
step "Turn ON: Prevent Storing of IP Addresses."
step "Turn ON: Data Scrubber, and Use Default Scrubbers."
note "Each switch saves as you flip it."
pause "Press Enter once all three are on."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Connect Sentry to Vercel"
open_url "https://vercel.com/integrations/sentry"
step "On the Marketplace page: Install → Link Existing Sentry Account → Continue."
step "Give it access to the potluck Vercel project only."
step "Sign in to Sentry if asked and pick the org $SENTRY_ORG_SLUG."
step "Link Sentry project potluck to Vercel project potluck."
warn "If it offers automatic uptime monitors, switch that OFF: stage 6 adds the one we want."
step "Finish the install."
note "It sets NEXT_PUBLIC_SENTRY_DSN, SENTRY_AUTH_TOKEN, SENTRY_ORG and SENTRY_PROJECT"
note "in Vercel. The token belongs to a \"Vercel Internal Integration\" in Sentry's"
note "Developer Settings: deleting that breaks the integration."
note "\"Failed to fetch\" during setup is usually an ad blocker."
pause "Press Enter once the integration shows as installed."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Vercel: list the Sentry variables, names and targets only"
say "Nothing is deleted: previews send nothing (#66), and the token reaching"
say "previews waits for the secrets work."
# Read through Vercel's API, not `vercel link` (which can pull development
# variables into a file). The response can carry values, so jq reads only the
# key, target and git branch, straight from the pipe. jq's own errors can quote
# its input, so they're dropped.
listing=""
if ! listing=$(npx --yes "$VERCEL_CLI" api /v9/projects/potluck/env 2>/dev/null \
    | jq -r '(.envs // .)[]
             | select(.key | test("SENTRY"))
             | [.key,
                ((.target // []) | if type == "array" then join(",") else . end),
                (.gitBranch // "")]
             | @tsv' 2>/dev/null); then
  listing=""
fi
if [[ -z "$listing" ]]; then
  warn "Couldn't list them. Sign in with: npx $VERCEL_CLI login, then re-run."
  SKIPPED+=("list Vercel's Sentry variables (names and targets, never values)")
else
  printf '\n  %s%-24s %-34s %s%s\n' "$BOLD" "NAME" "TARGETS" "GIT BRANCH" "$RESET"
  while IFS=$'\t' read -r name targets branch; do
    printf '  %-24s %-34s %s\n' "$name" "$targets" "$branch"
  done <<< "$listing"
  printf '\n'
  for key in "${SENTRY_KEYS[@]}"; do
    if awk -F'\t' -v k="$key" '$1 == k && $2 ~ /(^|,)production(,|$)/ { found = 1 } END { exit !found }' <<< "$listing"; then
      printf '  %s✓%s %s reaches production\n' "$GREEN" "$RESET" "$key"
    else
      warn "$key doesn't reach production"
      SKIPPED+=("$key isn't set for production: check the Sentry integration's project link")
    fi
  done
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Sentry: uptime monitor on the liveness route"
open_url "https://sentry.io/organizations/$SENTRY_ORG_SLUG/issues/"
step "In the sidebar, open Monitors, then create an Uptime Monitor."
step "Project: potluck. Name: Potluck liveness."
step "URL: $LIVENESS_URL"
step "Method: GET. Interval: 5 minutes. No headers, no body."
step "Leave Allow Sampling OFF (the app sends no traces) and the tolerances as they are."
step "Create it."
say "Then email yourself when it goes down:"
step "Monitors → Alerts → create an alert on issues from the uptime monitor"
step "  (its downtime issues), with the action: email you."
note "The liveness route never touches the database, so a cold Neon doesn't page you."
pause "Press Enter once the monitor and its email alert exist."

finish
note "Data region: $SENTRY_REGION. Tell Claude: it goes on the privacy page (#67)."
note "Production has no DSN until its next build: the privacy page's merge."
note "After that deploy, throw the test error on the deploy's own URL (not the public one):"
note "  /api/test-error/g/SentryTestNotARealLink, with vercel curl."
printf '\n'
}

run_wizard "$@"; exit
